var STORY = [{"n":1,"title":"Opening, meet Jeff","splash":false,"layout":"wide strip on top, a tall panel and a small panel side by side in the middle, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top Third","desc":"Dawn over Durian City, a state of the art city like Makati. Glass towers catching the golden sunrise, wide avenues, colorful jeepneys driving along them, a few palm and durian trees along the street.","lines":[{"k":"cap","who":"","mod":"","t":"\"Durian City, Mindanao. 6:42 AM.\""},{"k":"sfx","who":"","mod":"giongo","t":"VROOOM, HONK HONK"},{"k":"sfx","who":"","mod":"gitaigo","t":"KINANG (the towers shining in the sunrise)"}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Tall, Middle Left","desc":"The gate of Durian City High School. Flag, painted sign, students trickling in, the modern skyline behind the school.","lines":[{"k":"sfx","who":"","mod":"giseigo","t":"DALDAL DALDAL (the chatter of the crowd)"},{"k":"sfx","who":"","mod":"giseigo","t":"BULONG BULONG (students whisper as Jeff walks by: \"That's the folklore guy.\")"},{"k":"sfx","who":"","mod":"giongo","t":"KRIIIK (the gate swinging)"}],"rect":[3.0,24.58,49.96,27.24]},{"n":3,"size":"Small, Middle Right","desc":"Close up: a necklace swinging against a blue uniform shirt. One tiny glint. No explanation.","lines":[{"k":"sfx","who":"","mod":"gitaigo","t":"KISLAP, TIBOK (a tiny glint and a tiny heartbeat, like the necklace is alive)"}],"rect":[55.36,24.58,41.64,27.24]},{"n":4,"size":"Large Low Angle, Bottom Half","desc":"Jeff walks toward the camera. Ube colored hair in the wind, one hand in his pocket, the other holding a thick book on Philippine folklore. Tall, lean, effortless.","lines":[{"k":"sfx","who":"","mod":"giongo","t":"SWISH (hair in the wind), TAP TAP (footsteps)"},{"k":"sfx","who":"","mod":"gitaigo","t":"KINTAB (a cool glow around Jeff)"},{"k":"cap","who":"","mod":"","t":"\"Jefferson Victorio. He looks like the cool one.\""},{"k":"cap","who":"","mod":"","t":"\"His classmates call him weird. He reads about ancient spirits for breakfast.\""}],"rect":[3.0,53.42,94.0,43.58]}]},{"n":2,"title":"Meet Hal","splash":false,"layout":"wide strip on top, two small panels, then a tall panel on the left and a large panel on the right.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"Behind Jeff, a tiny figure sprints through the crowd, a backpack bigger than he is.","lines":[{"k":"sfx","who":"","mod":"","t":"TAP TAP TAP TAP"}],"rect":[3.0,3.0,94.0,22.7]},{"n":2,"size":"Small","desc":"Jeff does not turn around. Small smirk.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Three. Two. One.\""}],"rect":[3.0,27.3,45.8,18.16]},{"n":3,"size":"Small","desc":"Hal crashes into Jeff's back. Glasses slide down his nose.","lines":[{"k":"sfx","who":"","mod":"","t":"THUD"},{"k":"say","who":"Hal","mod":"","t":"\"JEFF! Wait up!\""}],"rect":[51.2,27.3,45.8,18.16]},{"n":4,"size":"Tall, Left","desc":"Hal's face close up. Brown hair, round glasses, big eyes. He is very cute and very offended.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"You walked past the bakery again! I texted you six times!\""}],"rect":[3.0,47.06,36.64,49.94]},{"n":5,"size":"Large, Right","desc":"The height gap. Jeff looks down, Hal looks up, a paper bag of pandesal held high like a trophy.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I got your favorite.\""},{"k":"say","who":"Jeff","mod":"","t":"\"You're a legend.\""},{"k":"cap","who":"","mod":"","t":"\"Hal Bautista. Loudest voice in any room.\""}],"rect":[42.04,47.06,54.96,49.94]}]},{"n":3,"title":"Meet Mel","splash":false,"layout":"wide strip on top, a tall panel on the left, three stacked small panels in the middle, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"Violin music drifts across the school grounds. Students stop on the stairs. Glowing musical notes weave through the air.","lines":[],"rect":[3.0,3.0,94.0,14.53]},{"n":2,"size":"Tall, Left","desc":"Mel on the school steps, eyes closed, long blonde hair over his shoulder, violin tucked under his chin. A very big, very gentle guy.","lines":[],"rect":[3.0,19.13,41.22,39.95]},{"n":3,"size":"Small","desc":"Jeff and Hal arrive at the bottom of the steps. Hal waves with the pandesal bag.","lines":[],"rect":[46.62,19.13,50.38,12.25]},{"n":4,"size":"Small","desc":"Mel opens his eyes and smiles without stopping the music.","lines":[],"rect":[46.62,32.98,50.38,12.25]},{"n":5,"size":"Small","desc":"Mel's bow slows, then stops.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Good morning. I made something new.\""}],"rect":[46.62,46.83,50.38,12.25]},{"n":6,"size":"Large, Bottom","desc":"The trio together. Hal has climbed two steps to reach Mel's shoulder height. Jeff leans on the railing with his book.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"It sounds like sunrise.\""},{"k":"say","who":"Hal","mod":"","t":"\"It sounds like pandesal.\""},{"k":"say","who":"Mel","mod":"","t":"\"Both are correct.\""},{"k":"cap","who":"","mod":"","t":"\"Mel Charlie Abaldado. The violin is the one thing that always makes sense to him.\""}],"rect":[3.0,60.68,94.0,36.32]}]},{"n":4,"title":"Meet Nikki","splash":false,"layout":"wide strip on top, a small panel and a tall panel, a large low angle panel in the middle, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"The gate opens. Wind. A group of girls in white blouses and skirts. No dialogue.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Hal freezes mid bite.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"...No.\""}],"rect":[3.0,22.44,45.8,23.19]},{"n":3,"size":"Tall","desc":"Students step aside, one after another, like a slow wave.","lines":[],"rect":[51.2,22.44,45.8,23.19]},{"n":4,"size":"Large Low Angle","desc":"Nikki walks forward, hair in the wind, her friends flanking her. She owns the sidewalk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Nikki Sharon Legazpi. The most popular girl in school.\""}],"rect":[3.0,47.23,94.0,26.76]},{"n":5,"size":"Medium, Bottom","desc":"She stops in front of the trio. Smug.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Look. The nerd, the giant, and the pocket edition.\""}],"rect":[3.0,75.59,94.0,21.41]}]},{"n":5,"title":"Nikki picks on Hal","splash":false,"layout":"small panel, wide panel, three small panels in a row, and a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal bristles, finger raised.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I am NOT a pocket edition!\""}],"rect":[3.0,3.0,27.48,19.98]},{"n":2,"size":"Wide","desc":"Nikki plucks his glasses off his face and holds them high. Her friends laugh.","lines":[],"rect":[32.88,3.0,64.12,19.98]},{"n":3,"size":"Small","desc":"Hal's blurry point of view: smears of color and shapes.","lines":[{"k":"say","who":"Hal","mod":"thought bubble","t":"\"I can't see anything\""}],"rect":[3.0,24.58,29.73,21.79]},{"n":4,"size":"Small","desc":"Hal jumping, fingertips short of the glasses.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Aww. He can't even jump.\""}],"rect":[35.13,24.58,29.73,21.79]},{"n":5,"size":"Small","desc":"Mel lowers the violin, troubled.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Nikki, please. Those are his.\""}],"rect":[67.27,24.58,29.73,21.79]},{"n":6,"size":"Medium, Bottom","desc":"Jeff calm. His necklace swings once against his chest.","lines":[],"rect":[3.0,47.97,94.0,49.03]}]},{"n":6,"title":"Jeff steps in","splash":false,"layout":"wide panel, two medium panels, a small panel, and a large panel at the bottom that ends on a cliffhanger.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jeff steps between Nikki and Hal. We see his back. Hal peeks out behind his arm.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Medium","desc":"Jeff, steady.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Give them back.\""},{"k":"say","who":"Nikki","mod":"","t":"\"Make me.\""}],"rect":[3.0,20.66,45.8,19.62]},{"n":3,"size":"Medium","desc":"Jeff's smirk.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Do you ever get tired of being this predictable?\""},{"k":"say","who":"Nikki","mod":"","t":"\"Do you ever get tired of reading about ghosts?\""}],"rect":[51.2,20.66,45.8,19.62]},{"n":4,"size":"Small","desc":"Hal, from behind Jeff.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"They're not ghosts. It's folklore!\""},{"k":"say","who":"Mel","mod":"off panel","t":"\"It's technically mythology.\""}],"rect":[3.0,41.88,94.0,12.49]},{"n":5,"size":"Large","desc":"Nikki, smug and annoyed, flings Hal's glasses high over Jeff's head in a big arc, her arm swung out in a showy throw, with speed lines and a glint on the lenses. Her friends gasp.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Fine. Go fetch.\""},{"k":"sfx","who":"","mod":"","t":"FLING"}],"rect":[3.0,55.97,94.0,41.03]}]},{"n":7,"title":"Jeff proves the point","splash":true,"layout":"one full page image.","note":"this is the page that shows Jeff is more than the weird folklore kid. Everyone else in the frame is in comic shock, Jeff is the only calm face. He looks cool, and for one moment the school sees it. Nikki's girls fall for him on the spot.","panels":[{"n":1,"size":"Full Page","desc":"Jeff, without even turning around, reaches up and catches the glasses between two fingers, calm and stylish. Dramatic angle from slightly below. Behind him Hal's eyes are huge, Mel's bow is frozen mid air, the students are frozen. Nikki's friends have their hands over their mouths and small hearts in their eyes. Leaves and dust float in a shaft of morning sun. Nikki's face is shocked.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Careful. Those are his.\""},{"k":"cap","who":"","mod":"tiny, bottom corner","t":"\"Jeff Victorio never starts a fight. He just never lets his friends stand alone.\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":8,"title":"Aftermath","splash":false,"layout":"wide panel, two small panels, a medium panel, a small panel, and a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Silence. Then a long dreamy sigh from Nikki's friends, with tiny hearts floating up. The school bell rings.","lines":[{"k":"sfx","who":"","mod":"","t":"KRIIIIING"}],"rect":[3.0,3.0,94.0,18.3]},{"n":2,"size":"Small","desc":"Nikki's friends crowd around Jeff, starry eyed.","lines":[{"k":"say","who":"Nikki'S Friend","mod":"","t":"\"He caught it without even looking.\""},{"k":"say","who":"Nikki'S Other Friend","mod":"","t":"\"Okay, who knew?\""}],"rect":[3.0,22.9,45.8,20.58]},{"n":3,"size":"Small","desc":"Nikki, jaw tight, a stiff smile, snatches up her bag.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Nice catch, Jeff. Finally, a use for all that ghost reading.\""}],"rect":[51.2,22.9,45.8,20.58]},{"n":4,"size":"Medium","desc":"Jeff gently puts the glasses back on Hal and straightens them.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Thanks, Jeff.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Don't mention it. Actually, mention it. I want credit.\""}],"rect":[3.0,45.08,55.76,27.45]},{"n":5,"size":"Small","desc":"Hal laughs through wet eyes.","lines":[],"rect":[61.16,45.08,35.84,27.45]},{"n":6,"size":"Wide, Bottom","desc":"The three walk toward the school, Mel playing softly. Far behind them, Nikki drags her friends along, and the friends keep looking back at Jeff. Nikki glances back for half a second.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Whatever. Come on, girls.\""},{"k":"say","who":"Nikki'S Friend","mod":"","t":"\"Nik?\""},{"k":"say","who":"Nikki","mod":"","t":"\"Nothing.\""}],"rect":[3.0,74.13,94.0,22.87]}]},{"n":9,"title":"Homeroom, meet Sir Archie","splash":false,"layout":"wide panel on top, small panel, medium panel, small panel, large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Homeroom. Ceiling fans, chalk dust, open windows with a view of the courtyard.","lines":[],"rect":[3.0,3.0,94.0,16.34]},{"n":2,"size":"Small","desc":"Sir Archie at the front. Cool, tall, muscular young teacher with white hair and rectangle glasses, tight buttoned shirt and a cardigan, a coffee thermos on the desk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Mr. Archibald Oronies. Everyone calls him Sir Archie.\""}],"rect":[3.0,20.94,23.79,21.79]},{"n":3,"size":"Medium","desc":"Roll call, quick cuts of each of the four.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Victorio?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Present, sir.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Bautista?\""},{"k":"say","who":"Hal","mod":"","t":"\"Here, Sir! Alive!\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Abaldado?\" MEL: \"Present.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Legazpi?\" NIKKI: \"...Present.\""}],"rect":[29.19,20.94,41.63,21.79]},{"n":4,"size":"Small","desc":"Seats: the three in a row, Nikki one row ahead. She turns to glare at them.","lines":[],"rect":[73.21,20.94,23.79,21.79]},{"n":5,"size":"Large","desc":"Sir Archie writes on the board in big letters: SANGKAPULUAN.","lines":[],"rect":[3.0,44.34,94.0,52.66]}]},{"n":10,"title":"The lesson","splash":false,"layout":"medium panel, wide illustrated panel, small panel, medium panel, small panel, small panel.","note":"","panels":[{"n":1,"size":"Medium","desc":"Sir Archie.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Before we start, a story. Long ago, our ancestors called these islands the Sangkapuluan.\""}],"rect":[3.0,3.0,36.64,31.13]},{"n":2,"size":"Wide","desc":"The islands drawn like an ancient map. Ten small points glow along the map.","lines":[{"k":"cap","who":"","mod":"","t":"\"Ten.\""}],"rect":[42.04,3.0,54.96,31.13]},{"n":3,"size":"Small","desc":"Hal whispers.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Ten what?\""},{"k":"say","who":"Jeff","mod":"whispering back, eyes sparkling","t":"\"Agimats.\""}],"rect":[3.0,35.73,36.64,28.54]},{"n":4,"size":"Medium","desc":"Sir Archie.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Every land has its Agimats. Charms with a power of their own. Ten are said to sleep in the Sangkapuluan, our islands.\""}],"rect":[42.04,35.73,54.96,28.54]},{"n":5,"size":"Small","desc":"Nikki, bored.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"So it's a fairy tale, Sir?\" The class laughs."},{"k":"say","who":"Sir Archie","mod":"","t":"\"Every fairy tale begins with someone who stopped listening.\""}],"rect":[3.0,65.87,45.8,31.13]},{"n":6,"size":"Small","desc":"Jeff's hand drifts to his collar and closes around the necklace.","lines":[],"rect":[51.2,65.87,45.8,31.13]}]},{"n":11,"title":"The first gods","splash":false,"layout":"medium panel, wide panel, two small panels, a large panel at the bottom.","note":"every myth panel on pages 11 to 14 is drawn in a different style from the present day, heavy black ink and rough woodcut texture, like an old Filipino manuscript.","panels":[{"n":1,"size":"Medium","desc":"Sir Archie taps the word on the board. For once the class is quiet.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Before the islands were islands, there was only sea and sky.\""}],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Wide","desc":"Myth panel, drawn like an old inked manuscript. Nothing but a flat endless sea under an endless sky. Two presences fill them: Maguayan below in the water, Captan above in the clouds.","lines":[{"k":"cap","who":"","mod":"","t":"\"Maguayan, the sea. Captan, the sky.\""}],"rect":[3.0,22.44,94.0,19.62]},{"n":3,"size":"Small","desc":"Myth panel. The sea and the sky meet at the horizon. Where they touch, two shapes form: Lidagat, a woman of water, and Lihangin, a man of wind.","lines":[{"k":"cap","who":"","mod":"","t":"\"Their children. Lidagat the sea, Lihangin the wind.\""}],"rect":[3.0,43.66,45.8,16.06]},{"n":4,"size":"Small","desc":"Back in the classroom. Hal with his chin on the desk, actually listening for once.","lines":[{"k":"say","who":"Hal","mod":"whispering","t":"\"Wait. The sky and the sea had kids?\""},{"k":"say","who":"Mel","mod":"whispering","t":"\"Everything has kids in these stories.\""}],"rect":[51.2,43.66,45.8,16.06]},{"n":5,"size":"Large","desc":"Myth panel. Four young gods standing in the open space between sea and sky, hair streaming in the wind. Licalibutan at the front, broad and stone skinned. Liadlao glowing warm gold. Libulan pale and silver. Lisuga the smallest, scattered with points of light.","lines":[{"k":"cap","who":"","mod":"","t":"\"And their children were four.\""},{"k":"sfx","who":"","mod":"","t":"\"HIHIP\""}],"rect":[3.0,61.32,94.0,35.68]}]},{"n":12,"title":"What Licalibutan wanted","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Myth panel. The four of them in the empty between place. Licalibutan stares up at the gate of the sky, far above.","lines":[{"k":"say","who":"Licalibutan","mod":"","t":"\"We live in the space between our grandfathers. Not sea. Not sky. Nothing of our own.\""}],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Myth panel. Liadlao, warm and uneasy.","lines":[{"k":"say","who":"Liadlao","mod":"","t":"\"It has always been enough.\""},{"k":"say","who":"Licalibutan","mod":"","t":"\"Enough is a word for people who are given things.\""}],"rect":[3.0,22.44,45.8,16.06]},{"n":3,"size":"Small","desc":"Myth panel. Libulan looks away. He has already decided.","lines":[],"rect":[51.2,22.44,45.8,16.06]},{"n":4,"size":"Medium","desc":"Myth panel. Lisuga, the youngest, silver and small, pulls at Licalibutan's arm.","lines":[{"k":"say","who":"Lisuga","mod":"","t":"\"Kuya. Please.\""}],"rect":[3.0,40.1,94.0,19.62]},{"n":5,"size":"Large","desc":"Myth panel. Licalibutan raises his fist toward the sky gate. Liadlao and Libulan rise behind him. Lisuga is left on the ground, reaching after them.","lines":[{"k":"say","who":"Licalibutan","mod":"","t":"\"Then we take one.\""},{"k":"cap","who":"","mod":"","t":"\"He was not wrong. That is what made them follow.\""},{"k":"sfx","who":"","mod":"","t":"\"UGONG\""}],"rect":[3.0,61.32,94.0,35.68]}]},{"n":13,"title":"The lightning","splash":true,"layout":"one full page image.","note":"the grand event of the lesson. Heaviest blacks in the chapter so far. No dialogue, only the caption and the sound.","panels":[{"n":1,"size":"Large","desc":"Splash page, myth panel. The three brothers hammer at the gate of the sky. Above them Captan rises enormous, his face lost in shadow, one open hand coming down with lightning forking out of it. The light is pure white, everything else is black. Far below, Lisuga is a tiny silver speck, still reaching up.","lines":[{"k":"cap","who":"","mod":"","t":"\"Captan did not want to destroy them. He wanted the sky to hold.\""},{"k":"sfx","who":"","mod":"","t":"\"KIDLAT\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":14,"title":"What was left","splash":false,"layout":"three small panels, a wide panel, a small panel, a large panel at the bottom.","note":"the necklace under Jeff's collar is warm. Do not show it glowing yet, only Jeff noticing the light.","panels":[{"n":1,"size":"Small","desc":"Myth panel. Libulan's pale body cooling in the dark, pulling itself round.","lines":[{"k":"cap","who":"","mod":"","t":"\"Libulan became the moon.\""}],"rect":[3.0,3.0,29.73,17.84]},{"n":2,"size":"Small","desc":"Myth panel. Liadlao's gold body catching light and burning.","lines":[{"k":"cap","who":"","mod":"","t":"\"Liadlao became the sun.\""}],"rect":[35.13,3.0,29.73,17.84]},{"n":3,"size":"Small","desc":"Myth panel. Lisuga's silver body bursting apart into countless small lights.","lines":[{"k":"cap","who":"","mod":"","t":"\"Lisuga, who never wanted the war, became the stars.\""}],"rect":[67.27,3.0,29.73,17.84]},{"n":4,"size":"Wide","desc":"Myth panel. Licalibutan's broken rock body falls into the sea and shatters. The pieces settle and spread, and they are islands.","lines":[{"k":"cap","who":"","mod":"","t":"\"And Licalibutan became the ground we are standing on.\""},{"k":"sfx","who":"","mod":"","t":"\"LAGABOG\""}],"rect":[3.0,22.44,94.0,17.84]},{"n":5,"size":"Small","desc":"Myth panel. Maguayan's hand presses one seed into the broken rock. A bamboo shoot rises out of it.","lines":[{"k":"cap","who":"","mod":"","t":"\"Then the sea planted a wish in the wreckage.\""}],"rect":[3.0,41.88,94.0,14.27]},{"n":6,"size":"Large","desc":"Back in the classroom. Late morning sun comes through the window and lays a bar of gold across Jeff's desk and his hands. Sir Archie is watching him. Jeff is staring at the light, not at the board.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"The Sangkapuluan. Our islands. A broken brother, and a wish planted in him.\""},{"k":"cap","who":"","mod":"","t":"\"Hiraya.\""},{"k":"sfx","who":"","mod":"","t":"\"KINANG\""}],"rect":[3.0,57.75,94.0,39.25]}]},{"n":15,"title":"After school","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The school gate in the golden afternoon light. The bell has rung. Students stream out. The three friends split at the gate.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I have to get home early. Mama needs me.\""},{"k":"say","who":"Mel","mod":"","t":"\"Violin lesson. See you tomorrow.\""},{"k":"say","who":"Hal","mod":"","t":"\"Science club. I'm building a robot. It's going to be taller than me.\""}],"rect":[3.0,3.0,94.0,19.62]},{"n":2,"size":"Small","desc":"The three wave and head off in different directions.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TAP TAP\""}],"rect":[3.0,24.22,45.8,16.06]},{"n":3,"size":"Small","desc":"Far down the school wall, a tall, slender boy leans alone with his hands in his pockets and earbuds in. Nobody looks at him.","lines":[],"rect":[51.2,24.22,45.8,16.06]},{"n":4,"size":"Medium","desc":"Close up on him. Long dark emo hair over one eye, a small nose piercing, tattoos down his right arm, a spiked belt and stacks of bracelets. He wears the same blue school shirt and khaki pants as everyone else, but worn the punk way.","lines":[{"k":"cap","who":"","mod":"","t":"\"Jared Callao. Spikes outside, quiet inside.\""}],"rect":[3.0,41.88,94.0,12.49]},{"n":5,"size":"Large","desc":"A huge shadow falls over Jared. He pulls out one earbud and looks up. Dan Macabebe stands in front of him, blocking the whole path.","lines":[{"k":"cap","who":"","mod":"","t":"\"Dan Macabebe. Big. Loud. Allergic to being told no.\""},{"k":"say","who":"Dan","mod":"","t":"\"Well, well. Still wearing your costume, freak?\""}],"rect":[3.0,55.97,94.0,41.03]}]},{"n":16,"title":"The bully","splash":false,"layout":"a large panel and a tall panel, two small panels, a wide panel at the bottom.","note":"show the shoving and the cruelty, but nothing graphic. Jared only gets slight bruises. The point is that he is alone and nobody helps.","panels":[{"n":1,"size":"Large","desc":"Dan shoves Jared back against the wall with one hand on his chest.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"Nice hair. Nice nose ring. Who are you trying to scare?\""},{"k":"say","who":"Jared","mod":"","t":"\"Get off me.\""}],"rect":[3.0,3.0,59.54,36.32]},{"n":2,"size":"Tall","desc":"Jared's face close up. Cold, calm eyes behind the hair. His jaw is set. He does not fight back.","lines":[],"rect":[64.94,3.0,32.06,36.32]},{"n":3,"size":"Small","desc":"Jared tries to walk away. Dan grabs his bag strap and yanks him back.","lines":[{"k":"sfx","who":"","mod":"","t":"\"YANK\""}],"rect":[3.0,40.92,45.8,18.16]},{"n":4,"size":"Small","desc":"Dan shoves Jared down. Jared catches himself on his arm and scrapes it on the ground.","lines":[{"k":"sfx","who":"","mod":"","t":"\"THUD\""}],"rect":[51.2,40.92,45.8,18.16]},{"n":5,"size":"Wide","desc":"Wide shot of the path. Dan towering over Jared on the ground. A few students walk past in the background, look the other way, and keep walking. No one stops.","lines":[],"rect":[3.0,60.68,94.0,36.32]}]},{"n":17,"title":"No one helps","splash":false,"layout":"two small panels, a wide panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Dan rips one of Jared's bracelets off his wrist.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SNAP\""}],"rect":[3.0,3.0,45.8,16.34]},{"n":2,"size":"Small","desc":"Jared on the ground, still. He does not cry out. He just stares.","lines":[],"rect":[51.2,3.0,45.8,16.34]},{"n":3,"size":"Wide","desc":"Dan walks away with his arms behind his head, laughing. The laughter fills the empty street.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"Go cry about it, freak!\""}],"rect":[3.0,20.94,94.0,19.98]},{"n":4,"size":"Large","desc":"Jared alone on the ground. He picks up the broken bracelet. A small scrape on his cheek, a fresh bruise on his forearm. His hands shake, but he says nothing and does not look around for help.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SHAKE SHAKE\""}],"rect":[3.0,42.52,94.0,54.48]}]},{"n":18,"title":"The walk home","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"do not show any violence at home, ever, on these pages. Fear, sound and shadow only.","panels":[{"n":1,"size":"Wide","desc":"Jared walks home along a quiet road at dusk, earbuds in, bag over his shoulder, his long shadow stretched behind him. The road is lined with old trees.","lines":[],"rect":[3.0,3.0,94.0,19.62]},{"n":2,"size":"Small","desc":"Jared touches the scrape on his cheek and looks at his fingers.","lines":[{"k":"say","who":"Jared","mod":"thinking","t":"\"It doesn't even hurt.\""}],"rect":[3.0,24.22,45.8,17.84]},{"n":3,"size":"Small","desc":"Jared slows down. His steps get heavier, and he stares at the road.","lines":[{"k":"say","who":"Jared","mod":"thinking","t":"\"Not like what's waiting at home.\""}],"rect":[51.2,24.22,45.8,17.84]},{"n":4,"size":"Medium","desc":"A memory panel, drawn in washed gray tones: a dark kitchen, a table crowded with empty bottles, a man's shadow on the wall, and a woman's trembling hands gripping the edge of a sink. Nothing violent is shown, only fear.","lines":[{"k":"cap","who":"","mod":"","t":"\"At home there is a father who drinks, and a mother who is afraid.\""},{"k":"say","who":"Dad","mod":"from the memory, muffled","t":"\"WHERE'S MY DINNER?!\""}],"rect":[3.0,43.66,94.0,17.84]},{"n":5,"size":"Large","desc":"Jared stops, picks up a stone, and throws it as hard as he can toward a huge old balete tree at the side of the road, with a long, silent, angry shout.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"AAAAARGH!\""},{"k":"sfx","who":"","mod":"","t":"\"FWOOSH\""}],"rect":[3.0,63.1,94.0,33.9]}]},{"n":19,"title":"The Agta","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"DRAFT. The Agta is a mean spirited demon like spirit that preys on hatred and amplifies it. The design is a to do (see the todo list). Keep it a dark shape with red eyes for now.","panels":[{"n":1,"size":"Wide","desc":"The stone hits the trunk of the old balete tree.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TOK!\""}],"rect":[3.0,3.0,94.0,18.16]},{"n":2,"size":"Small","desc":"Jared, already walking away, staring at his empty hand. He does not feel better.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"...That didn't help.\""}],"rect":[3.0,22.76,45.8,12.71]},{"n":3,"size":"Small","desc":"Behind him, the tree is still. Then the dark between the roots seems to breathe. A leaf falls. The wind stops. The air turns cold.","lines":[{"k":"sfx","who":"","mod":"","t":"\"...TIBOK\""}],"rect":[51.2,22.76,45.8,12.71]},{"n":4,"size":"Large","desc":"High in the branches, two red eyes open. A long, thin, shadowy figure curls around the branch, a crooked grin full of teeth. It looks down at Jared's back as he walks away.","lines":[{"k":"cap","who":"","mod":"","t":"\"The Agta. A hundred years of sleep, and a very bad mood.\""},{"k":"say","who":"Agta","mod":"","t":"\"Oh... what a delicious little hate.\""}],"rect":[3.0,37.07,94.0,59.93]}]},{"n":20,"title":"Jeff comes home","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jeff's family home at evening, drawn from the home reference: a two storey house with a concrete ground floor, a woven bamboo upper floor, a wooden balcony and a tile gable roof, its windows glowing. Papa's jeepney is parked in the carport with its hood open. The sign above its windshield reads PILIPINAS.","lines":[{"k":"cap","who":"","mod":"","t":"\"Meanwhile.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jeff opens the door and steps in, bag on his shoulder.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I'm home.\""}],"rect":[3.0,26.39,45.8,16.34]},{"n":3,"size":"Small","desc":"Inside the house: a small door bursts open, and two blurred shapes charge down the hall.","lines":[{"k":"sfx","who":"","mod":"","t":"\"PAT PAT PAT PAT\""}],"rect":[51.2,26.39,45.8,16.34]},{"n":4,"size":"Medium","desc":"Two five year old twin girls leap at Jeff and grab one leg each.","lines":[{"k":"cap","who":"","mod":"","t":"\"Gail and Janelle. Five years old. Professional huggers.\""},{"k":"say","who":"Gail","mod":"","t":"\"KUYA!\""},{"k":"say","who":"Janelle","mod":"","t":"\"KUYA'S HOME!\""}],"rect":[3.0,44.34,45.8,52.66]},{"n":5,"size":"Medium","desc":"Jeff with a twin on each leg like a pair of koalas, a flat annoyed stare, ears turning slightly red.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Get off. I just got home.\""},{"k":"say","who":"Gail","mod":"","t":"\"No.\""},{"k":"say","who":"Janelle","mod":"","t":"\"Never.\""}],"rect":[51.2,44.34,45.8,52.66]}]},{"n":21,"title":"Two koalas","splash":false,"layout":"two small panels, a medium panel and a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Jeff drags himself down the hall, a twin clinging to each leg. Deadpan.","lines":[{"k":"sfx","who":"","mod":"","t":"\"DRAG DRAG\""}],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Janelle holds up a drawing of a purple haired stick figure.","lines":[{"k":"say","who":"Janelle","mod":"","t":"\"I drew you, Kuya!\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Medium","desc":"Jeff looks at the drawing. The stick figure has a huge head and a tiny body, and a banana hat.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Why do I have a banana on my head?\""},{"k":"say","who":"Janelle","mod":"","t":"\"Because you're handsome.\""},{"k":"say","who":"Jeff","mod":"","t":"\"...That doesn't make sense.\""}],"rect":[3.0,22.76,54.96,27.24]},{"n":4,"size":"Small","desc":"Gail sticks a heart sticker on Jeff's cheek while he's distracted.","lines":[],"rect":[60.36,22.76,36.64,27.24]},{"n":5,"size":"Large","desc":"Jeff tries to look annoyed, with a sticker on his cheek and a twin on each leg. His mouth fights a tiny smile and loses. Mama's voice calls from the kitchen.","lines":[{"k":"say","who":"Mama","mod":"from the kitchen","t":"\"Girls! Let your Kuya breathe!\""},{"k":"say","who":"Gail And Janelle","mod":"","t":"\"NO!\""}],"rect":[3.0,51.6,94.0,45.4]}]},{"n":22,"title":"Dinner with Mama","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The family kitchen. A table with steaming rice and tinola. Mama, with an apron and a ladle in her hand, is at the stove.","lines":[{"k":"cap","who":"","mod":"","t":"\"Mama. Runs the house like a general, with soup.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jeff sits and starts eating. The twins sit on either side of him.","lines":[{"k":"sfx","who":"","mod":"","t":"\"NOM NOM\""}],"rect":[3.0,26.39,45.8,23.61]},{"n":3,"size":"Small","desc":"Mama sets down a bowl and studies him closely.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"So? How was school?\""}],"rect":[51.2,26.39,45.8,23.61]},{"n":4,"size":"Medium","desc":"Jeff, mouth full.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Good. Nobody died.\""},{"k":"say","who":"Mama","mod":"","t":"\"That's your standard now?\""},{"k":"say","who":"Jeff","mod":"","t":"\"It's a high standard, Ma.\""}],"rect":[3.0,51.6,45.8,45.4]},{"n":5,"size":"Medium","desc":"Mama, with the ladle in one hand, narrows her eyes.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"And Hal? Is he still eating enough? That poor little boy.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Ma, he's not little. He's compact.\""}],"rect":[51.2,51.6,45.8,45.4]}]},{"n":23,"title":"Mama and the twins","splash":false,"layout":"two small panels, three wide panels stacked below.","note":"","panels":[{"n":1,"size":"Small","desc":"Mama slides a piece of fish onto Jeff's plate.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"Eat more. You're too thin.\""}],"rect":[3.0,3.0,45.8,19.62]},{"n":2,"size":"Small","desc":"Janelle's little hand sneaks across the table and steals the fish from Jeff's plate.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SNATCH\""}],"rect":[51.2,3.0,45.8,19.62]},{"n":3,"size":"Wide","desc":"Jeff, without even looking, takes the fish back from her fork. Janelle gasps. Gail gives her a thumbs up.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Nice try.\""},{"k":"say","who":"Janelle","mod":"","t":"\"...How?\""},{"k":"say","who":"Jeff","mod":"","t":"\"I have eyes in the back of my head.\""}],"rect":[3.0,24.22,94.0,23.19]},{"n":4,"size":"Wide","desc":"Mama, leaning on the table with her chin in her hand and a sly smile.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"And any girlfriend I should know about?\""}],"rect":[3.0,49.02,94.0,23.19]},{"n":5,"size":"Wide","desc":"Jeff chokes on his rice. The twins burst into giggles.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Ma! Eat your own rice!\""},{"k":"say","who":"Gail","mod":"","t":"\"Kuya has a girlfriend!\""},{"k":"say","who":"Janelle","mod":"","t":"\"Kuya has a banana girlfriend!\""},{"k":"sfx","who":"","mod":"","t":"\"COUGH COUGH\""}],"rect":[3.0,73.81,94.0,23.19]}]},{"n":24,"title":"Papa","splash":false,"layout":"wide panel, two small panels, a large panel and a medium panel at the bottom.","note":"Hint only, not explained yet. Papa's old carved charm is a Babaylan symbol. The reveal that he was a Babaylan comes later. TO CONFIRM when.","panels":[{"n":1,"size":"Wide","desc":"The door at the back of the kitchen swings open. A tall man stands in the doorway, backlit by the carport light, a grease stained towel over his shoulder.","lines":[{"k":"sfx","who":"","mod":"","t":"\"CREAK\""}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"The man's face: tired eyes, a faint smile, grease smudged on his cheek. A small carved wooden charm hangs from a cord around his neck.","lines":[{"k":"cap","who":"","mod":"","t":"\"Papa. Jeepney driver. Grease is his cologne.\""}],"rect":[3.0,24.58,45.8,16.34]},{"n":3,"size":"Small","desc":"Papa, with a nod toward the carport.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Jeff. The jeepney is coughing again. Come help me.\""}],"rect":[51.2,24.58,45.8,16.34]},{"n":4,"size":"Large","desc":"The carport of the house. The jeepney sits with its hood open, a work lamp hanging over the engine. Jeff and Papa lean over the engine side by side, in the same posture, with the same frown.","lines":[{"k":"sfx","who":"","mod":"","t":"\"COUGH SPUTTER\""}],"rect":[3.0,42.52,54.96,54.48]},{"n":5,"size":"Medium","desc":"Papa hands Jeff a wrench.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Hold this. No, the other one.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Pa, they're the same wrench.\""},{"k":"say","who":"Papa","mod":"","t":"\"The other one.\""}],"rect":[60.36,42.52,36.64,54.48]}]},{"n":25,"title":"The jeepney talk","splash":false,"layout":"two small panels, a large panel, two small panels at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Papa, bent over the engine with a flashlight in his teeth, eyes on the engine.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Mama says your marks are high again.\""}],"rect":[3.0,3.0,45.8,21.79]},{"n":2,"size":"Small","desc":"Jeff, tightening a bolt.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"They're okay.\""}],"rect":[51.2,3.0,45.8,21.79]},{"n":3,"size":"Large","desc":"Papa takes the flashlight out of his mouth and looks at Jeff over the open hood, one eyebrow up, with the work lamp lighting his face from below.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"High marks. Every time. You're not cheating, are you?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Pa. I just study. A lot.\""}],"rect":[3.0,26.39,94.0,36.32]},{"n":4,"size":"Small","desc":"Jeff, eyes sparkling.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"That way, when I'm done, I'm free.\""}],"rect":[3.0,64.31,45.8,32.69]},{"n":5,"size":"Small","desc":"Papa, with a sly half smile.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Free for what?\""}],"rect":[51.2,64.31,45.8,32.69]}]},{"n":26,"title":"Arnis","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"optional beat, TO CONFIRM. Papa pauses for a second and looks out toward the dark street, as if he felt something. Then he shakes it off. A hint that Babaylan senses never fully retire.","panels":[{"n":1,"size":"Wide","desc":"The back wall of the carport. Two worn rattan sticks hang on hooks above a tool bench. Jeff glances at them, then back at his father.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Arnis. You promised to teach me the next form.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Papa chuckles and shakes his head.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"A son who studies hard so he can get hit with sticks.\""}],"rect":[3.0,26.39,45.8,21.79]},{"n":3,"size":"Small","desc":"Papa, with a fond look.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Your mother is proud and worried at the same time.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Mostly proud?\""}],"rect":[51.2,26.39,45.8,21.79]},{"n":4,"size":"Large","desc":"Papa reaches in and turns the key. The jeepney's engine roars to life, its headlights blazing. Father and son look at the machine, then at each other, with the same grin.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Finish the engine first. Then the sticks.\""},{"k":"sfx","who":"","mod":"","t":"\"VROOOOM\""}],"rect":[3.0,49.78,94.0,47.22]}]},{"n":27,"title":"Jared at home","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"nothing violent is shown here either. Sound, shadow and Jared's face only.","panels":[{"n":1,"size":"Wide","desc":"Night. A small, narrow house with one dim upstairs window. Inside, Jared's room: band posters, a desk lamp, a notebook, a cracked mirror. The broken bracelet lies on the desk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Jared's house.\""}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"Jared sits at the desk with headphones around his neck, opens the notebook, and tries to draw.","lines":[],"rect":[3.0,24.58,45.8,18.16]},{"n":3,"size":"Small","desc":"From downstairs, the muffled sound of a TV and a man's slurred shouting. We only see the floor and a thin line of light under the door.","lines":[{"k":"say","who":"Dad","mod":"muffled, from downstairs","t":"\"WHERE'S MY DINNER?!\""},{"k":"sfx","who":"","mod":"","t":"\"CRASH\""}],"rect":[51.2,24.58,45.8,18.16]},{"n":4,"size":"Medium","desc":"Jared puts the headphones on and presses them against his ears, eyes squeezed shut, the veins in his temples showing.","lines":[{"k":"sfx","who":"","mod":"","t":"\"THROB THROB\""}],"rect":[3.0,44.34,45.8,52.66]},{"n":5,"size":"Medium","desc":"Through the headphones, a small, frightened voice from downstairs. Jared's fist closes on the pencil and it snaps.","lines":[{"k":"say","who":"Mama","mod":"muffled, from downstairs","t":"\"Please... lower your voice...\""},{"k":"sfx","who":"","mod":"","t":"\"SNAP\""}],"rect":[51.2,44.34,45.8,52.66]}]},{"n":28,"title":"What Jared tells himself","splash":false,"layout":"large panel, two small panels, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"Jared sits on the edge of his bed, staring at the broken bracelet in his palm. His reflection in the cracked mirror is split in two.","lines":[{"k":"say","who":"Jared","mod":"muttering","t":"\"I'm taller than him now. I could stop him.\""}],"rect":[3.0,3.0,94.0,45.4]},{"n":2,"size":"Small","desc":"Jared, looking away.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"But every time, I just... stand there.\""}],"rect":[3.0,50.0,45.8,18.16]},{"n":3,"size":"Small","desc":"Jared, jaw tight.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"I can't even stand up to Dan. How am I supposed to stand up to him?\""}],"rect":[51.2,50.0,45.8,18.16]},{"n":4,"size":"Wide","desc":"Jared clenches his fist on his knee. The lamp flickers. Behind him, the curtain stirs, though the window is closed.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"I hate this. I hate him. I hate that I can't do anything.\""},{"k":"sfx","who":"","mod":"","t":"\"THROB\""}],"rect":[3.0,69.76,94.0,27.24]}]},{"n":29,"title":"The watcher","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jared's house from outside at night, one window lit. A huge old tree stands beside it, its branches reaching toward the roof.","lines":[],"rect":[3.0,3.0,94.0,27.24]},{"n":2,"size":"Small","desc":"A branch bends. Two red eyes open in the leaves.","lines":[],"rect":[3.0,31.84,45.8,18.16]},{"n":3,"size":"Small","desc":"The Agta, crouched on the branch outside Jared's window, tilts its head and sniffs the air.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SNIFF\""}],"rect":[51.2,31.84,45.8,18.16]},{"n":4,"size":"Large","desc":"Close up of the Agta's grin, with the lit window of Jared's room reflected in its red eyes. Through the glass, Jared is a tiny figure on the edge of his bed.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"I can feel it from here. The anger. The shame. So much hate, for a boy who has so little.\""},{"k":"say","who":"Agta","mod":"softly","t":"\"Let me help you with that.\""}],"rect":[3.0,51.6,94.0,45.4]}]},{"n":30,"title":"Lights out","splash":false,"layout":"two small panels, a wide panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Jared rubs his eyes and closes the notebook.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Just sleep. Tomorrow's the same anyway.\""}],"rect":[3.0,3.0,45.8,21.79]},{"n":2,"size":"Small","desc":"He takes off his spiked belt and bracelets and sets them on the desk one by one. Without them, he looks a lot younger.","lines":[],"rect":[51.2,3.0,45.8,21.79]},{"n":3,"size":"Wide","desc":"Jared crosses the room and stops by the door, next to the light switch. Downstairs, the shouting has stopped. The house is quiet.","lines":[],"rect":[3.0,26.39,94.0,18.16]},{"n":4,"size":"Large","desc":"Jared, standing by the switch with one hand raised. His shadow stretches long across the wall behind him. In the dark window, behind his reflection, two red eyes.","lines":[{"k":"say","who":"Jared","mod":"quietly, toward the floor","t":"\"Good night, Ma.\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":31,"title":"The merge","splash":false,"layout":"wide panel, three small panels, a large panel at the bottom.","note":"DRAFT. This is the scary beat of the chapter, so use a lot of black.","panels":[{"n":1,"size":"Wide","desc":"Jared's hand flips the switch. The room goes black. Jared stands in the dark, not moving yet.","lines":[{"k":"sfx","who":"","mod":"","t":"\"CLICK\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Moonlight through the window. The curtain waves.","lines":[],"rect":[3.0,26.39,29.73,18.16]},{"n":3,"size":"Small","desc":"The tree outside rattles. The branch where the Agta sat is empty.","lines":[],"rect":[35.13,26.39,29.73,18.16]},{"n":4,"size":"Small","desc":"A dark shape launches from the branch, arms wide.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SWOOSH\""}],"rect":[67.27,26.39,29.73,18.16]},{"n":5,"size":"Large","desc":"The Agta flies through the window like smoke, the glass stays whole, and dives into the long shadow on the floor behind Jared. The shadow ripples. For one second, the shadow has red eyes. Jared, still standing in the dark, notices nothing.","lines":[{"k":"sfx","who":"","mod":"","t":"\"ZUUUUM\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":32,"title":"Sleep","splash":false,"layout":"wide panel, two small panels, a wide panel, a large panel at the bottom.","note":"the light is the banaag, the first glimmer (the chapter title). The dream sequence starts here. DRAFT, the creator will add the details.","panels":[{"n":1,"size":"Wide","desc":"Jared's shadow on the floor, in the moonlight. It is a little too long and a little too dark, and its shape does not quite match Jared's.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Jared lies down on the bed, tired.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Why am I so tired all of a sudden...\""}],"rect":[3.0,22.44,45.8,17.84]},{"n":3,"size":"Small","desc":"He pulls the blanket up to his chin.","lines":[],"rect":[51.2,22.44,45.8,17.84]},{"n":4,"size":"Wide","desc":"His eyes close. His breathing slows.","lines":[{"k":"sfx","who":"","mod":"","t":"\"ZZZ\""}],"rect":[3.0,41.88,94.0,17.84]},{"n":5,"size":"Large","desc":"A pure black panel. Far in the center, one tiny faint light, a glimmer of dawn, grows slowly brighter.","lines":[{"k":"cap","who":"","mod":"","t":"\"And so Jared dreamed.\""}],"rect":[3.0,61.32,94.0,35.68]}]},{"n":33,"title":"The dream","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"no violence is shown. The father is only a shadow. This is a memory turned into a nightmare.","panels":[{"n":1,"size":"Wide","desc":"Jared opens his eyes inside the dream. He stands in his own kitchen, but everything is gray and stretched, the ceiling too high, the table too long. Empty bottles cover the table.","lines":[{"k":"cap","who":"","mod":"","t":"\"In the dream, the house was bigger. Or he was smaller.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jared looks at his hands. They are a child's hands. He is seven years old again, in pajamas.","lines":[],"rect":[3.0,26.39,45.8,18.16]},{"n":3,"size":"Small","desc":"A huge man's shadow fills the wall above him. No face, only the shadow and a bottle in its hand.","lines":[{"k":"sfx","who":"","mod":"","t":"\"THUD THUD\""}],"rect":[51.2,26.39,45.8,18.16]},{"n":4,"size":"Large","desc":"Little Jared backs into a corner under the giant shadow, arms over his head. The floor behind him is cracking open into pure black.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Stop... please stop...\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":34,"title":"The offer","splash":false,"layout":"two small panels, a wide panel, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"A long thin hand reaches out of the black crack in the floor and rests on little Jared's shoulder.","lines":[],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Little Jared turns. Two glowing eyes and a crooked grin float in the dark behind him.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"Poor little thing. Always the small one.\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Wide","desc":"The Agta rises behind him, long and thin, its arms wrapping the corner like smoke. The giant shadow of the father freezes on the wall.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"You hate him. You hate the big boy at school. You hate yourself most of all. I can taste it.\""}],"rect":[3.0,22.76,94.0,25.42]},{"n":4,"size":"Medium","desc":"Little Jared, trembling, but looking up at the Agta.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Who are you?\""},{"k":"say","who":"Agta","mod":"","t":"\"A friend who was asleep. You woke me with a stone.\""}],"rect":[3.0,49.78,45.8,47.22]},{"n":5,"size":"Medium","desc":"The Agta holds out its long hand, palm up. A small black flame burns in it.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"Give me the hate. I will make you tall.\""}],"rect":[51.2,49.78,45.8,47.22]}]},{"n":35,"title":"The deal","splash":true,"layout":"one full page image.","note":"one page image, the grand event of the middle of the chapter. Heavy black, the eyes and the grin are the only white.","panels":[{"n":1,"size":"Large","desc":"Splash page. Jared, grown again and standing tall, takes the black flame. His shadow rises behind him as the huge grinning Agta, many times his size, its arms spread across the whole page. The father's shadow is small now, and it shrinks at the edge of the page.","lines":[{"k":"cap","who":"","mod":"","t":"\"And Jared, who had never been tall enough, said yes.\""},{"k":"say","who":"Jared","mod":"","t":"\"...Make them stop.\""},{"k":"sfx","who":"","mod":"","t":"\"FWOOOM\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":36,"title":"Morning","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"Jared's mother is seen only from behind or in part. Her design is open.","panels":[{"n":1,"size":"Wide","desc":"Morning light in Jared's room. He sits up in bed, wide awake. The room looks the same. The broken bracelet is on the desk.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TIK TAK\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jared touches his cheek. The scrape is gone.","lines":[{"k":"say","who":"Jared","mod":"thinking","t":"\"It doesn't hurt. Nothing hurts.\""}],"rect":[3.0,26.39,45.8,18.16]},{"n":3,"size":"Small","desc":"He puts on his spiked belt and bracelets. His shadow on the wall puts them on half a second late.","lines":[],"rect":[51.2,26.39,45.8,18.16]},{"n":4,"size":"Medium","desc":"Downstairs. His mother at the sink with her back turned, a plate of fried egg and rice waiting on the table. The father is not in the room, only his snoring from the sofa off panel.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"Jared? You're up early. Eat first.\""},{"k":"sfx","who":"","mod":"","t":"\"ZZZ\""}],"rect":[3.0,46.15,45.8,50.85]},{"n":5,"size":"Medium","desc":"Jared at the door, looking back at her. For one panel he is just a tired boy who loves his mother.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"I'll be okay today, Ma.\""}],"rect":[51.2,46.15,45.8,50.85]}]},{"n":37,"title":"The necklace","splash":false,"layout":"wide panel, two small panels, a large panel and a small panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Morning at Jeff's family home. Papa wipes the jeepney's windshield in the carport. The twins wave from the balcony.","lines":[{"k":"cap","who":"","mod":"","t":"\"The same morning.\""},{"k":"say","who":"Gail And Janelle","mod":"","t":"\"BYE KUYA!\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jeff at the gate, bag on his shoulder, half a pandesal in his mouth.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Bye. Don't draw on my notebooks.\""}],"rect":[3.0,26.39,45.8,16.34]},{"n":3,"size":"Small","desc":"Close up of the necklace against his shirt. It gives one tiny glint.","lines":[{"k":"sfx","who":"","mod":"","t":"\"KISLAP\""}],"rect":[51.2,26.39,45.8,16.34]},{"n":4,"size":"Large","desc":"Papa has stopped wiping. He stares at the necklace, then down the street toward the school. The carved charm on his own neck sways with no wind.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Jeff.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Hm?\""}],"rect":[3.0,44.34,59.54,52.66]},{"n":5,"size":"Small","desc":"Papa, after a pause, with an easy smile that does not reach his eyes.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Nothing. Come straight home after class.\""}],"rect":[64.94,44.34,32.06,52.66]}]},{"n":38,"title":"Walking in","splash":false,"layout":"wide panel, three small panels, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The road to school. Jeff, Hal and Mel walk together. Hal carries a cardboard box with a robot arm sticking out of it.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Behold. Robot Hal. He is one foot taller than me.\""},{"k":"say","who":"Mel","mod":"","t":"\"So he is normal height.\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"Hal, deeply offended.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Mel. I trusted you.\""}],"rect":[3.0,28.21,29.73,19.98]},{"n":3,"size":"Small","desc":"Jeff rubs his chest where the necklace sits.","lines":[{"k":"say","who":"Jeff","mod":"thinking","t":"\"It's warm.\""}],"rect":[35.13,28.21,29.73,19.98]},{"n":4,"size":"Small","desc":"Nikki and her friends pass them at the gate. Nikki flicks her hair and does not look at Jeff. Her friends wave at him behind her back.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Morning, weirdo.\""}],"rect":[67.27,28.21,29.73,19.98]},{"n":5,"size":"Medium","desc":"By the gate, Jared walks in alone, hands in his pockets. Students make room without knowing why. His shadow is longer than it should be in the morning sun.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TIBOK\""}],"rect":[3.0,49.78,94.0,47.22]}]},{"n":39,"title":"Sir Archie's question","splash":false,"layout":"wide panel, two small panels, a medium panel and a small panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Homeroom. Sir Archie at the board with his coffee. On the board: SPIRITS OF THE TREES.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Our elders said some trees are not empty. Who can name what lives in a balete?\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"Jeff's hand is up before the question ends.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Engkanto. Kapre. Tikbalang. And in the Visayas, the Agta.\""}],"rect":[3.0,28.21,45.8,18.16]},{"n":3,"size":"Small","desc":"Nikki, chin on her hand.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Of course he knows.\""}],"rect":[51.2,28.21,45.8,18.16]},{"n":4,"size":"Medium","desc":"Sir Archie, with his storyteller eyes.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"The Agta. Tall, dark, fond of old trees. They say it sleeps for years. They say you should never throw things at its house.\""}],"rect":[3.0,47.97,59.54,49.03]},{"n":5,"size":"Small","desc":"At the back of the room, Jared, staring at his desk. His fist tightens.","lines":[],"rect":[64.94,47.97,32.06,49.03]}]},{"n":40,"title":"What it eats","splash":false,"layout":"two small panels, a wide panel, a large panel at the bottom.","note":"a hint that Sir Archie sees more than a teacher should.","panels":[{"n":1,"size":"Small","desc":"Hal raises his hand.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Sir, what does it eat?\""}],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Sir Archie sips his coffee.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Stories differ. My lola said it eats what we refuse to let go of.\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Wide","desc":"The class laughs nervously. The ceiling fan slows for a second, then spins again.","lines":[{"k":"sfx","who":"","mod":"","t":"\"WUP... WUP... WUP\""}],"rect":[3.0,22.76,94.0,19.98]},{"n":4,"size":"Large","desc":"Sir Archie looks straight at the back of the room, over his glasses. Jared looks up. For a moment the two lock eyes. Behind Jared, his shadow on the wall is turned the wrong way, facing the teacher.","lines":[{"k":"say","who":"Sir Archie","mod":"thinking","t":"\"...Hm.\""}],"rect":[3.0,44.34,94.0,52.66]}]},{"n":41,"title":"Dan again","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"After class, the same path along the school wall. Dan Macabebe waits with two friends, cracking his knuckles.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"There's my favorite freak.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jared keeps walking with his head down.","lines":[],"rect":[3.0,26.39,45.8,18.16]},{"n":3,"size":"Small","desc":"Dan's hand lands on Jared's chest and stops him.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"I'm talking to you.\""}],"rect":[51.2,26.39,45.8,18.16]},{"n":4,"size":"Medium","desc":"Jared lifts his head. Calm. Too calm. A small smile.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Take your hand off.\""}],"rect":[3.0,46.15,45.8,50.85]},{"n":5,"size":"Medium","desc":"Dan laughs and winds up for a shove. On the ground, Jared's shadow has already raised its arm.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"Or what?\""}],"rect":[51.2,46.15,45.8,50.85]}]},{"n":42,"title":"Tall","splash":false,"layout":"a tall panel and two small panels stacked beside it, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Tall","desc":"Jared catches Dan's wrist in one hand. Dan's arm stops dead.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TAK\""}],"rect":[3.0,3.0,45.8,40.66]},{"n":2,"size":"Small","desc":"Dan's face, confused, trying to pull free.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"H-hey. Let go.\""}],"rect":[51.2,3.0,45.8,19.53]},{"n":3,"size":"Small","desc":"Jared's eye through his hair. The pupil is a thin white ring.","lines":[],"rect":[51.2,24.13,45.8,19.53]},{"n":4,"size":"Large","desc":"Jared lifts Dan off the ground by the wrist, with one arm. Dan's feet kick in the air. His two friends drop their bags and run. Jared's shadow on the wall is huge, long armed and grinning.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"You said I was a freak.\""},{"k":"say","who":"Agta","mod":"from the shadow","t":"\"Show him.\""}],"rect":[3.0,45.26,94.0,51.74]}]},{"n":43,"title":"Too far","splash":false,"layout":"two small panels, a wide panel, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Dan, crying now, all the meanness gone.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"I'm sorry! I'm sorry! Put me down!\""}],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Jared's face twitches. A flash of the real Jared, scared of himself.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"I... I don't...\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Wide","desc":"Students at the end of the path stop and stare. Phones come out. Nobody steps forward.","lines":[{"k":"sfx","who":"","mod":"","t":"\"BULONG BULONG\""}],"rect":[3.0,22.76,94.0,21.79]},{"n":4,"size":"Medium","desc":"The shadow's long hand closes over Jared's own shoulder from behind, and his face goes blank again.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"Don't stop now. This is the best part.\""}],"rect":[3.0,46.15,45.8,50.85]},{"n":5,"size":"Medium","desc":"A voice from the end of the path. Jeff, with Hal and Mel behind him, the necklace bright against his shirt.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"That's enough.\""}],"rect":[51.2,46.15,45.8,50.85]}]},{"n":44,"title":"Jeff steps in, again","splash":false,"layout":"wide panel, two small panels, a medium panel and a small panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jeff walks down the path toward Jared, calm, hands open. Hal and Mel hang back. Nikki arrives behind the crowd and pushes through.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Jeff. Jeff. He is holding Dan like a grocery bag.\""},{"k":"say","who":"Mel","mod":"","t":"\"I see it.\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"Jeff, eyes on Jared, not on Dan.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Jared, right? Put him down. He's not worth it.\""}],"rect":[3.0,28.21,45.8,18.16]},{"n":3,"size":"Small","desc":"Jared's head turns slowly toward Jeff. Then the shadow's head turns too, a beat later.","lines":[],"rect":[51.2,28.21,45.8,18.16]},{"n":4,"size":"Medium","desc":"The Agta's eyes open in the shadow on the wall and fix on the necklace.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"Oh. That light. I know that light.\""},{"k":"sfx","who":"","mod":"","t":"\"KISLAP\""}],"rect":[3.0,47.97,59.54,49.03]},{"n":5,"size":"Small","desc":"Jeff, looking at the wall, not at Jared.","lines":[{"k":"say","who":"Jeff","mod":"thinking","t":"\"The shadow is looking at me.\""}],"rect":[64.94,47.97,32.06,49.03]}]},{"n":45,"title":"The drop","splash":false,"layout":"two small panels, a wide panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Jared's hand opens. Dan falls.","lines":[{"k":"sfx","who":"","mod":"","t":"\"THUD\""}],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Nikki grabs Dan by the collar and drags him backward, away from Jared.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Move, you big idiot! Move!\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Wide","desc":"Dan scrambles away on hands and knees. Nikki stands between him and Jared for a second, shaking but not running.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Victorio! Whatever you're doing, do it faster!\""}],"rect":[3.0,22.76,94.0,21.79]},{"n":4,"size":"Large","desc":"Jared steps toward Jeff. With every step the shadow behind him peels off the wall and stands up, long and thin, twice as tall as the school wall.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"A child of the sun. Asleep, like I was. How lucky for me.\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":46,"title":"Arnis","splash":false,"layout":"wide panel, three small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The shadow's long arm whips across the path toward Jeff.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SWOOSH\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jeff's eyes. Sharp, like on page 7.","lines":[],"rect":[3.0,26.39,29.73,18.16]},{"n":3,"size":"Small","desc":"His hand snatches a broom leaning on the wall.","lines":[],"rect":[35.13,26.39,29.73,18.16]},{"n":4,"size":"Small","desc":"He snaps the broom head off against his knee.","lines":[{"k":"sfx","who":"","mod":"","t":"\"KRAK\""}],"rect":[67.27,26.39,29.73,18.16]},{"n":5,"size":"Large","desc":"Jeff blocks the shadow arm with the stick in a clean Arnis guard, feet set, the necklace blazing. The shadow arm bursts into smoke where the stick meets it.","lines":[{"k":"say","who":"Jeff","mod":"thinking","t":"\"Papa's first form. Don't think. Just stand.\""},{"k":"sfx","who":"","mod":"","t":"\"TAK!\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":47,"title":"It does not work twice","splash":false,"layout":"two small panels, a wide panel, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal, hiding behind Mel, pointing.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"HE HIT A SHADOW! WITH A BROOM!\""}],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Mel, already taking his violin case off his back and holding it like a shield.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Stay behind me.\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Wide","desc":"The smoke pulls back together. The Agta laughs, and the laugh comes out of Jared's mouth too.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"A stick. Against me. Your people have forgotten everything.\""}],"rect":[3.0,22.76,94.0,23.61]},{"n":4,"size":"Medium","desc":"Jared, tears running down a blank face, his own voice small under the laugh.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Help... I can't make it stop...\""}],"rect":[3.0,47.97,45.8,49.03]},{"n":5,"size":"Medium","desc":"Jeff lowers the stick a little, looking at Jared and not at the monster.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I hear you. Hold on.\""}],"rect":[51.2,47.97,45.8,49.03]}]},{"n":48,"title":"The shadow spreads","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The Agta slams both hands on the ground. Its shadow floods across the path like spilled ink, running under everyone's feet.","lines":[{"k":"sfx","who":"","mod":"","t":"\"FWOOOSH\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"The crowd of students runs. Phones fall. The shadow slides under Nikki's shoes before she can move.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"No no no no no\""}],"rect":[3.0,28.21,45.8,18.16]},{"n":3,"size":"Small","desc":"Hal looks down. His feet are sinking into the black as if it were water.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Mel. Mel. The floor is eating me.\""}],"rect":[51.2,28.21,45.8,18.16]},{"n":4,"size":"Large","desc":"From above: a wide pool of black on the path. Jeff, Hal, Mel and Nikki are caught in it up to their knees, with Jared and the Agta standing at the center. Outside the pool the school is normal, sunny, and nobody there seems to see them anymore.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"Come. Let me show the sun child where the old ones live.\""}],"rect":[3.0,47.97,94.0,49.03]}]},{"n":49,"title":"Pulled under","splash":false,"layout":"three small panels, a wide panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Mel grabs Hal by the back of the shirt with one hand and holds his violin case high with the other.","lines":[],"rect":[3.0,3.0,29.73,18.16]},{"n":2,"size":"Small","desc":"Nikki reaches out, and Jeff catches her wrist. The same catch as page 7, but this time to hold on.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Don't you dare let go!\""}],"rect":[35.13,3.0,29.73,18.16]},{"n":3,"size":"Small","desc":"Jeff reaches his other hand toward Jared.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Jared! Take my hand!\""}],"rect":[67.27,3.0,29.73,18.16]},{"n":4,"size":"Wide","desc":"Jared's fingers stretch toward Jeff's. They almost touch. The Agta's long hand closes around Jared's arm and pulls him down first.","lines":[],"rect":[3.0,22.76,94.0,21.79]},{"n":5,"size":"Large","desc":"The black closes over all of them. On the empty path, only the broken broom stick is left, rolling to a stop in the sun.","lines":[{"k":"sfx","who":"","mod":"","t":"\"GLUP\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":50,"title":"The fall","splash":false,"layout":"a tall panel and a tall panel side by side, a wide panel, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Tall","desc":"Pure black. The four fall, tiny figures, still holding on to each other in a chain: Mel, Hal, Jeff, Nikki.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"AAAAAAAAAAAAAAAA\""}],"rect":[3.0,3.0,45.8,45.4]},{"n":2,"size":"Tall","desc":"Shapes drift past them in the dark: roots as wide as roads, hanging lanterns of fireflies, a huge eye that opens and closes.","lines":[],"rect":[51.2,3.0,45.8,45.4]},{"n":3,"size":"Wide","desc":"Nikki, hair flying up, shouting at Jeff.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"This is your fault! I don't know how! But it is!\""}],"rect":[3.0,50.0,94.0,22.7]},{"n":4,"size":"Wide","desc":"Jeff's necklace. One small point of light in the black, growing.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TIBOK... TIBOK...\""}],"rect":[3.0,74.3,94.0,22.7]}]},{"n":51,"title":"Banaag","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The light from the necklace spreads like the first light before sunrise and wraps the four of them.","lines":[{"k":"cap","who":"","mod":"","t":"\"Banaag. The first glimmer.\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"Their fall slows. Hal opens one eye.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"...Are we dead? I didn't finish my robot.\""}],"rect":[3.0,28.21,45.8,18.16]},{"n":3,"size":"Small","desc":"Mel, calm, looking down.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"There's ground.\""}],"rect":[51.2,28.21,45.8,18.16]},{"n":4,"size":"Large","desc":"They drop gently through a ceiling of giant leaves, in a ball of soft light, toward a floor of roots and glowing moss.","lines":[{"k":"sfx","who":"","mod":"","t":"\"FWAAAH\""}],"rect":[3.0,47.97,94.0,49.03]}]},{"n":52,"title":"Landing","splash":false,"layout":"wide panel, three small panels, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The four land in a heap on thick moss. The light fades back into the necklace.","lines":[{"k":"sfx","who":"","mod":"","t":"\"POF\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"Hal, face down in the moss.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I am alive. Barely. Tell my robot I loved him.\""}],"rect":[3.0,28.21,29.73,19.98]},{"n":3,"size":"Small","desc":"Nikki sits up, pulls a leaf out of her hair, and realizes Jeff is still holding her wrist.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"...You can let go now.\""}],"rect":[35.13,28.21,29.73,19.98]},{"n":4,"size":"Small","desc":"Jeff lets go at once, ears red.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Right. Sorry.\""}],"rect":[67.27,28.21,29.73,19.98]},{"n":5,"size":"Medium","desc":"Mel is the first to stand. He is looking up, and for once his calm face is gone.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Guys. Look up.\""}],"rect":[3.0,49.78,94.0,47.22]}]},{"n":53,"title":"The other side","splash":true,"layout":"one full page image.","note":"one page image, the grand event of the end of the chapter. The name of this world is OPEN.","panels":[{"n":1,"size":"Large","desc":"Splash page. The four stand tiny at the foot of a balete tree as big as a mountain, its hanging roots like towers. The sky has two suns low on the horizon and stars at the same time. Fireflies in rivers. Far off between the roots, shapes are watching: a kapre's glowing cigar high in a tree, a tikbalang's long silhouette on a ridge, tiny duwende lights in the grass.","lines":[{"k":"cap","who":"","mod":"","t":"\"The elders had a name for the place behind the trees. The friends would learn it soon.\""},{"k":"say","who":"Jeff","mod":"","t":"\"It's real. All of it is real.\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":54,"title":"It has begun","splash":false,"layout":"wide panel, two small panels, a medium panel and a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Durian City, the same afternoon. The empty path by the school wall. Sir Archie picks up the broken broom stick and looks at the ground where there is no shadow at all.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"So it has started.\""}],"rect":[3.0,3.0,94.0,23.61]},{"n":2,"size":"Small","desc":"Jeff's family home. In the carport, the carved charm on Papa's neck cracks down the middle.","lines":[{"k":"sfx","who":"","mod":"","t":"\"KRAK\""}],"rect":[3.0,28.21,45.8,18.16]},{"n":3,"size":"Small","desc":"Papa's eyes, wide. The tired jeepney driver is gone. This is the face of a Babaylan.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Jeff.\""}],"rect":[51.2,28.21,45.8,18.16]},{"n":4,"size":"Medium","desc":"In the other world, far above the four friends, the Agta crouches on a root with Jared limp under its arm, grinning down.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"Welcome home, sun child.\""}],"rect":[3.0,47.97,45.8,49.03]},{"n":5,"size":"Medium","desc":"Jeff looks up at it and tightens his grip on nothing. His stick is gone. The necklace glows once.","lines":[{"k":"cap","who":"","mod":"","t":"\"End of Chapter 1: Banaag.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Give him back.\""}],"rect":[51.2,47.97,45.8,49.03]}]}];
